const API="../api/admin.php",fontChoices={"Noto Kufi Arabic":"Noto Kufi Arabic — modern geometric","Tajawal":"Tajawal — clean contemporary","Cairo":"Cairo — strong and readable","Noto Naskh Arabic":"Noto Naskh Arabic — traditional","Alexandria":"Alexandria — compact modern"};
const seed={menu:structuredClone(window.NUZHA_MENU||[]),gallery:structuredClone([...(window.NUZHA_GALLERY||[]),...(window.NUZHA_SYNCED_GALLERY||[])]),reviews:[],settings:{englishName:"Nuzha Restaurant",arabicName:"مطعم ومطبخ النزهة",phone:"053 003 5292",whatsapp:"966530035292",facebook:"",google:"",tiktok:"",addressEn:"Prince Sultan bin Abdulaziz, Al Faisaliyah, King Fahd Road, Al Nairyah 37481, Saudi Arabia",addressAr:"الأمير سلطان بن عبدالعزيز، الفيصلية، شارع الملك فهد، النعيرية 37481",arabicHeadingFont:"Noto Kufi Arabic",arabicBodyFont:"Tajawal"}};
let data=structuredClone(seed),csrf="",view="dashboard",needsSetup=false;
const $=s=>document.querySelector(s),esc=(v="")=>String(v).replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
async function request(url,options={}){const headers={...(options.headers||{})};if(csrf)headers["X-CSRF-Token"]=csrf;if(options.body&&!headers["Content-Type"]&&!(options.body instanceof FormData))headers["Content-Type"]="application/json";const response=await fetch(url,{credentials:"same-origin",...options,headers});const result=await response.json().catch(()=>({ok:false,error:"Unexpected server response."}));if(!response.ok||!result.ok)throw new Error(result.error||"Request failed.");return result}
async function start(){try{const session=await request(`${API}?action=session`);needsSetup=session.needsSetup;csrf=session.csrf||"";if(session.authenticated)return openPortal();showAuth()}catch(e){showAuth(e.message)}}
function showAuth(message=""){authScreen.hidden=false;portal.hidden=true;setupTokenLabel.hidden=!needsSetup;authTitle.textContent=needsSetup?"Create the first administrator":"Administrator sign in";authIntro.textContent=needsSetup?"Enter the private setup token from config.php, then create a strong account.":"Use your authorized administrator account.";authSubmit.textContent=needsSetup?"Create secure account":"Sign in";authError.textContent=message}
authForm.onsubmit=async e=>{e.preventDefault();authError.textContent="";authSubmit.disabled=true;try{const payload={email:email.value,password:password.value};if(needsSetup)payload.setupToken=setupToken.value;const result=await request(`${API}?action=${needsSetup?"setup":"login"}`,{method:"POST",body:JSON.stringify(payload)});csrf=result.csrf;await openPortal()}catch(err){authError.textContent=err.message}finally{authSubmit.disabled=false}};
async function openPortal(){const result=await request(`${API}?action=content`);csrf=result.csrf||csrf;data=result.content?{...structuredClone(seed),...result.content,settings:{...seed.settings,...result.content.settings}}:structuredClone(seed);authScreen.hidden=true;portal.hidden=false;render()}
function heading(a,b){viewEyebrow.textContent=a;viewTitle.textContent=b}
function render(){document.querySelectorAll("#adminNav button").forEach(b=>b.classList.toggle("active",b.dataset.view===view));({dashboard:renderDashboard,menu:renderMenu,gallery:renderGallery,reviews:renderReviews,settings:renderSettings}[view]||renderDashboard)()}
function renderDashboard(){heading("ADMIN OVERVIEW","Welcome.");adminWorkspace.innerHTML=`<div class="stat-grid"><article class="stat-card"><span>Menu items</span><strong>${data.menu.length}</strong></article><article class="stat-card"><span>Gallery photos</span><strong>${data.gallery.length}</strong></article><article class="stat-card"><span>Guest reviews</span><strong>${data.reviews.length}</strong></article><article class="stat-card"><span>Storage</span><strong style="font-size:20px">Server database</strong></article></div><section class="panel"><h2>Secure production mode</h2><p>Changes are stored on the server and appear for all visitors after you press Save changes. Image uploads accept validated JPG, PNG and WebP files only.</p></section>`}
function renderMenu(){heading("MENU MANAGER","Dishes and prices.");adminWorkspace.innerHTML=`<section class="panel"><div class="toolbar"><button id="addMenu">+ Add menu item</button></div><div class="editor-list">${data.menu.map((x,i)=>`<article class="editor-card"><img src="../${esc(x.image)}" alt=""><div class="editor-fields"><input data-type="menu" data-i="${i}" data-key="nameEn" value="${esc(x.nameEn)}"><input dir="rtl" data-type="menu" data-i="${i}" data-key="nameAr" value="${esc(x.nameAr)}"><textarea data-type="menu" data-i="${i}" data-key="descEn">${esc(x.descEn)}</textarea><textarea dir="rtl" data-type="menu" data-i="${i}" data-key="descAr">${esc(x.descAr)}</textarea><input data-type="menu" data-i="${i}" data-key="category" value="${esc(x.category)}"><input data-type="menu" data-i="${i}" data-key="price" value="${esc(x.price)}"><input class="wide" data-type="menu" data-i="${i}" data-key="image" value="${esc(x.image)}"></div><button class="remove-btn" data-remove="menu" data-i="${i}">×</button></article>`).join("")}</div></section>`;addMenu.onclick=()=>{data.menu.unshift({category:"feasts",nameEn:"New item",nameAr:"صنف جديد",descEn:"",descAr:"",price:"—",image:"assets/logo.png"});renderMenu()}}
function renderGallery(){heading("GALLERY MANAGER","Upload and describe images.");adminWorkspace.innerHTML=`<section class="panel"><div class="toolbar"><label class="file-button">Upload gallery image<input id="galleryUpload" type="file" accept="image/jpeg,image/png,image/webp"></label></div><div class="editor-list">${data.gallery.map((x,i)=>`<article class="editor-card"><img src="../${esc(x.src)}" alt=""><div class="editor-fields"><input data-type="gallery" data-i="${i}" data-key="titleEn" value="${esc(x.titleEn)}"><input dir="rtl" data-type="gallery" data-i="${i}" data-key="titleAr" value="${esc(x.titleAr)}"><input data-type="gallery" data-i="${i}" data-key="category" value="${esc(x.category)}"><input data-type="gallery" data-i="${i}" data-key="src" value="${esc(x.src)}"></div><button class="remove-btn" data-remove="gallery" data-i="${i}">×</button></article>`).join("")}</div></section>`;galleryUpload.onchange=uploadImage}
async function uploadImage(e){const file=e.target.files[0];if(!file)return;const form=new FormData();form.append("image",file);try{const r=await request(`${API}?action=upload`,{method:"POST",body:form});data.gallery.unshift({src:r.path,category:"dishes",titleEn:file.name.replace(/\.[^.]+$/,"").replace(/[-_]+/g," "),titleAr:"صورة جديدة"});renderGallery();toast("Image uploaded—save content to publish it") }catch(err){alert(err.message)}}
function renderReviews(){heading("REVIEW MANAGER","Verified customer feedback.");adminWorkspace.innerHTML=`<section class="panel"><div class="toolbar"><button id="addReview">+ Add review</button></div><div class="editor-list">${data.reviews.map((x,i)=>`<article class="editor-card"><div class="editor-fields"><textarea data-type="reviews" data-i="${i}" data-key="en">${esc(x.en)}</textarea><textarea dir="rtl" data-type="reviews" data-i="${i}" data-key="ar">${esc(x.ar)}</textarea><input data-type="reviews" data-i="${i}" data-key="name" value="${esc(x.name)}"><input type="number" min="1" max="5" data-type="reviews" data-i="${i}" data-key="rating" value="${esc(x.rating)}"></div><button class="remove-btn" data-remove="reviews" data-i="${i}">×</button></article>`).join("")}</div></section>`;addReview.onclick=()=>{data.reviews.unshift({en:"",ar:"",name:"Customer",rating:5});renderReviews()}}
function fontOptions(selected){return Object.entries(fontChoices).map(([value,label])=>`<option value="${value}" ${selected===value?"selected":""}>${label}</option>`).join("")}
function renderSettings(){heading("SITE SETTINGS","Identity, contact and Arabic fonts.");const s=data.settings;adminWorkspace.innerHTML=`<section class="panel"><div class="settings-grid"><label>English name<input data-setting="englishName" value="${esc(s.englishName)}"></label><label>Arabic name<input dir="rtl" data-setting="arabicName" value="${esc(s.arabicName)}"></label><label>Arabic heading font<select data-setting="arabicHeadingFont">${fontOptions(s.arabicHeadingFont)}</select></label><label>Arabic body font<select data-setting="arabicBodyFont">${fontOptions(s.arabicBodyFont)}</select></label><div class="font-preview wide" id="fontPreview" dir="rtl"><strong>اجتمعوا حول المائدة واستمتعوا بالكرم.</strong><span>نكهات أصيلة مطهوة على مهل وولائم سخية نصنعها لمن تحبون.</span></div><label>Phone<input data-setting="phone" value="${esc(s.phone)}"></label><label>WhatsApp<input data-setting="whatsapp" value="${esc(s.whatsapp)}"></label><label class="wide">Facebook URL<input data-setting="facebook" value="${esc(s.facebook)}"></label><label class="wide">Google Business URL<input data-setting="google" value="${esc(s.google)}"></label><label class="wide">TikTok URL<input data-setting="tiktok" value="${esc(s.tiktok)}"></label><label class="wide">English address<textarea data-setting="addressEn">${esc(s.addressEn)}</textarea></label><label class="wide">Arabic address<textarea dir="rtl" data-setting="addressAr">${esc(s.addressAr)}</textarea></label></div></section>`;updateFontPreview()}
function updateFontPreview(){const p=$("#fontPreview");if(!p)return;p.querySelector("strong").style.fontFamily=`"${data.settings.arabicHeadingFont}",sans-serif`;p.querySelector("span").style.fontFamily=`"${data.settings.arabicBodyFont}",sans-serif`}
adminNav.onclick=e=>{const b=e.target.closest("button[data-view]");if(b){view=b.dataset.view;render()}};
adminWorkspace.addEventListener("input",e=>{const el=e.target;if(el.dataset.setting){data.settings[el.dataset.setting]=el.value;updateFontPreview()}if(el.dataset.type)data[el.dataset.type][+el.dataset.i][el.dataset.key]=el.dataset.key==="rating"?+el.value:el.value});
adminWorkspace.addEventListener("click",e=>{const b=e.target.closest("[data-remove]");if(b){data[b.dataset.remove].splice(+b.dataset.i,1);render()}});
saveAll.onclick=async()=>{saveAll.disabled=true;try{await request(`${API}?action=content`,{method:"POST",body:JSON.stringify(data)});toast("Changes published successfully")}catch(err){alert(err.message)}finally{saveAll.disabled=false}};
logoutBtn.onclick=async()=>{try{await request(`${API}?action=logout`,{method:"POST"})}finally{location.reload()}};
function toast(message){const el=document.querySelector("#toast");el.textContent=message;el.classList.add("show");setTimeout(()=>el.classList.remove("show"),2500)}
start();

